import{_ as e,a as r,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const k=JSON.parse('{"title":"Spark：用途、惰性执行与 DAG","description":"从订单聚合例解释transformation/action、collect、cache与checkpoint；附历史学习方向。","frontmatter":{"title":"Spark：用途、惰性执行与 DAG","description":"从订单聚合例解释transformation/action、collect、cache与checkpoint；附历史学习方向。","showdocs":{"topics":[{"id":"spark","title":"Spark","link":"/topics/spark/"},{"id":"architecture","title":"架构风格与模块边界","link":"/topics/architecture/"}],"kind":"DataFrame与惰性执行","scope":"general","audience":"general","group":"数据库与存储","summary":"从订单聚合例解释transformation/action、collect、cache与checkpoint；附历史学习方向。","status":"active","related":[{"title":"Spark 分区：shuffle、倾斜与计划排障","link":"/middleware/data-processing/spark/partition-diagnosis","kind":"分区与流语义","scope":"general","audience":"general"},{"title":"Spark：订单批处理完整工程与推导","link":"/middleware/data-processing/spark/plus/practice/batch-project","kind":"批处理完整工程","scope":"general","audience":"general"},{"title":"Spark：Structured Streaming 的时间与输出边界","link":"/middleware/data-processing/spark/plus/subjects/streaming","kind":"分区与流语义","scope":"general","audience":"general"},{"title":"Spark：DataFrame 与 SQL 的数据契约","link":"/middleware/data-processing/spark/plus/subjects/dataframe-sql","kind":"DataFrame与惰性执行","scope":"general","audience":"general"},{"title":"库存服务的端口与适配器实践","link":"/principles/distributed-architecture/architecture/cases/application","kind":"库存边界实践","scope":"general","audience":"general"}],"prev":{"text":"Spark：Structured Streaming 的时间与输出边界","link":"/middleware/data-processing/spark/plus/subjects/streaming"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Spark：Structured Streaming 的时间与输出边界","link":"/middleware/data-processing/spark/plus/subjects/streaming"},"next":false},"headers":[],"relativePath":"middleware/data-processing/spark/execution-model.md","filePath":"middleware/data-processing/spark/execution-model.md"}'),c={name:"middleware/data-processing/spark/execution-model.md"};function p(o,a,l,n,s,d){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="spark-用途、惰性执行与-dag" tabindex="-1">Spark：用途、惰性执行与 DAG <a class="header-anchor" href="#spark-用途、惰性执行与-dag" aria-label="Permalink to &quot;Spark：用途、惰性执行与 DAG&quot;">​</a></h1><h2 id="part-3" tabindex="-1">惰性 DAG、作业与物化 <a class="header-anchor" href="#part-3" aria-label="Permalink to &quot;惰性 DAG、作业与物化 {#part-3}&quot;">​</a></h2><p>前置：会读Python函数、SQL分组和文件路径。本文固定Apache Spark/PySpark 3.5.6版本族，运行前应核对所在集群版本；不是对4.x的兼容承诺。本轮只写作与静态解析，示例未执行，不启动Spark、JVM或外部服务。</p><p>本例将订单CSV读为 <code>read</code>，过滤合法订单得到 <code>accepted</code>，再按日期和客户聚合为 <code>result</code>；变量定义、SQL和输入文件见<a href="/middleware/data-processing/spark/plus/practice/batch-project#project">完整批处理项目</a>。阅读前可先沿该页的 batch.py 确认数据流；本页解释执行时机，不是另一套运行结果。</p><h3 id="part-3-actions" tabindex="-1">Spark transformation 与 action <a class="header-anchor" href="#part-3-actions" aria-label="Permalink to &quot;Spark transformation 与 action {#part-3-actions}&quot;">​</a></h3><p>Spark transformation 与 action的区别是是否触发结果物化。select、filter、groupBy构造惰性计算计划；show、count、collect与write等action才请求执行。read构建数据源关系，但模式推断和文件发现可能做额外工作，所以不要把“惰性”误解为任何API调用都绝不访问文件。</p><p>本例从read到accepted只描述关系；result.orderBy(...).show触发一次作业集合，随后write可能再次计算同一输入。一个action不必严格对应一个job，广播、子查询和AQE可能带来额外job。多个action若读取会变化的源，得到的甚至不是同一快照；真实对账要先固定输入版本。</p><h3 id="part-3-collect" tabindex="-1">Spark collect 风险 <a class="header-anchor" href="#part-3-collect" aria-label="Permalink to &quot;Spark collect 风险 {#part-3-collect}&quot;">​</a></h3><p>Spark collect 风险在于把全部结果搬进driver内存，分布式计算不会替客户端承担无限结果容量。toPandas同样有此问题；调大executor内存不能解决driver接收不下的结果。即使一行很小，亿级行仍可压垮进程。</p><p>本例只对按日期和客户汇总后的关系show(20)，它限制展示行数，但上游聚合仍可能扫描全量输入并shuffle。limit不能作为全量质量证明，take/toLocalIterator也不是完全免内存风险。大结果应写分布式存储，再用分布式统计与抽样核对，只有先证明体量有界时才collect。</p><h3 id="part-3-cache" tabindex="-1">Spark cache 与 checkpoint <a class="header-anchor" href="#part-3-cache" aria-label="Permalink to &quot;Spark cache 与 checkpoint {#part-3-cache}&quot;">​</a></h3><p>Spark cache 与 checkpoint解决不同问题。cache/persist主要复用昂贵计算，首次action才填充；分区被逐出或丢失时可按血缘重算，调用cache不等于结果已落盘。复用结束unpersist，避免给其他任务施加内存压力。只用一次的小表通常不需要缓存。</p><p>DataFrame.checkpoint把计算结果写入已配置的可靠存储并截断逻辑计划，适合迭代导致血缘过长等情况；返回的新DataFrame才引用检查点。localCheckpoint依赖执行器缓存，不能当可靠恢复点。批处理checkpoint与Structured Streaming的checkpoint目录用途不同，后者保存offset、状态与查询进度，既不是普通cache，也不是把任意新查询接上旧目录的通行证。本例为保持最小关系链不启用cache/checkpoint。</p><h3 id="part-3-sources" tabindex="-1">资料与版本核对 <a class="header-anchor" href="#part-3-sources" aria-label="Permalink to &quot;资料与版本核对 {#part-3-sources}&quot;">​</a></h3><p>英文以官方3.5.6固定版本文档为准；中文作者资料用于术语与入门路径，不据旧版教程推断3.5新增API。核对日期：2026-10-17。</p><ul><li><a href="https://spark.apache.org/docs/3.5.6/rdd-programming-guide.html" target="_blank" rel="noopener noreferrer">RDD编程指南</a></li><li><a href="https://spark.apache.org/docs/3.5.6/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.checkpoint.html" target="_blank" rel="noopener noreferrer">DataFrame.checkpoint</a></li><li><a href="https://dblab.xmu.edu.cn/blog/1709/" target="_blank" rel="noopener noreferrer">林子雨中文作者教程</a></li></ul><h2 id="part-1" tabindex="-1">大数据学习方向 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;大数据学习方向 {#part-1}&quot;">​</a></h2><p><span id="part-1-readme"></span></p><h3 id="part-1-大数据" tabindex="-1">大数据 <a class="header-anchor" href="#part-1-大数据" aria-label="Permalink to &quot;大数据 {#part-1-大数据}&quot;">​</a></h3><p>原文是课程方向清单，尚未包含实现教程。按学习内容归并如下：</p><ul><li>计算与处理：Hadoop、Spark、Flink、ETL 和数据仓库。</li><li>存储与架构：HBase、大数据架构、Linux 与云计算。</li><li>分析与应用：统计分析、可视化、推荐、反欺诈、数据挖掘和机器学习；Jupyter Notebook 是练习工具。</li></ul><p>可先阅读 <a href="#part-2">Spark 能力概览</a> 和 <a href="/middleware/storage-foundations/storage/plus/subjects/dataother">数据库分类</a>，再按具体工作目标选择方向。</p><h2 id="part-2" tabindex="-1">Spark <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;Spark {#part-2}&quot;">​</a></h2><p>简介</p><p>Apache Spark 是一个开源的大数据处理框架，它提供了高性能、通用的集群计算引擎，能够处理大规模数据集的并行计算任务。Spark 的主要功能和应用包括：</p><ol><li>批处理：Spark 提供了强大的批处理功能，可以高效地处理大规模的数据集。它支持使用高级的数据操作和转换算子，如过滤、映射、聚合等，以及复杂的数据分析和处理任务。</li><li>实时流处理：Spark Streaming 是 Spark 的流处理组件，可以处理实时数据流。它支持将实时数据流划分为小批次数据，并在每个批次上执行批处理操作，从而实现了近实时的流处理能力。</li><li>机器学习：Spark 提供了机器学习库（MLlib），包含了各种常见的机器学习算法和工具，如分类、回归、聚类、推荐系统等。这些算法可以在分布式环境下运行，利用 Spark 的并行计算能力，处理大规模的机器学习任务。</li><li>图计算：GraphX 提供图遍历、聚合与连接等能力，用于图结构数据分析和计算。</li><li>SQL 查询和数据集处理：Spark 提供了对结构化数据的支持，可以通过 Spark SQL 进行 SQL 查询和数据集处理。它支持常见的 SQL 查询操作，如过滤、聚合、连接等，并提供了 DataFrame 和 Dataset API，用于灵活地处理和转换结构化数据。</li></ol><p><a href="/topics/spark/">返回 Spark 专题</a> · <a href="/topics/spark/?route=p2-spark">继续学习路线</a></p>',27)])])}const u=e(c,[["render",p]]);export{k as __pageData,u as default};
